    static CoverageGoalDefinition TemperatureGoal(OrganizationOpportunitySnapshot card)=>new(1,"Atmospheric temperature sampling","How does air temperature vary with altitude?",card.Id,card.Revision,PreflightReadiness.Hash(card),"science:ambient-temperature:temperature","ambient-temperature","degC",CoverageEvidenceCategory.SyntheticFixture,Altitude:new(0,10000,2000),MinimumPilots:2);
    static async Task<CoverageGoalView> CoverageSave(SubmissionFixture f,OrganizationOpportunitySnapshot card,CoverageGoalDefinition definition,CoverageGoalView? previous=null)=> (await f.Server.Post(Progress+$"/campaigns/{card.CampaignId}/coverage/goals"+(previous is null?"":"/"+previous.Id),new CoverageGoalSave(1,Guid.NewGuid(),previous?.Revision??0,definition),previous is null?HttpMethod.Post:HttpMethod.Put)).Deserialize<CoverageGoalView>(WireJson.Options)!;
    static async Task<PersonalResearchAttempt> CoverageRecord(SubmissionFixture f,PreparedOrganizationMission p,int low,int high)
    {
        var start=DateTimeOffset.UtcNow;var time=start;using var research=new ResearchOperations(f.Store,f.Science);var coordinator=new MissionCoordinator(f.Store,1000,research:research,utcNow:()=>time);var plan=f.Store.SavePlan(p.Plan with{Instruments=[new("ambient-temperature",true),new("ambient-pressure",true)],StartScienceArmed=true});var seconds=((high-low)/500+1)*4-1;
        void Observe(int i){time=start.AddSeconds(i);var frame=SubmissionFixture.Frame(time) with{AltitudeMslFeet=low+Math.Min((high-low)/500,i/4)*500};coordinator.Apply(new(new(ConnectionState.Connected,frame.Source,"Explicit synthetic atmosphere",time),frame,new(time,20-i*.1,29.9,5,270,.002)));}
        Observe(0);var flight=coordinator.Start(new("Synthetic three-pilot atmospheric observations",PlanId:plan.Id));var state=coordinator.ScienceCollection(flight.Id)!.State!;coordinator.ControlScience(new(1,flight.Id,Guid.NewGuid(),state.Revision,CollectionAction.StartData,null));for(var i=1;i<=seconds;i++)Observe(i);await Task.Delay(TimeSpan.FromSeconds(seconds));coordinator.End(flight.Id);return f.Store.EvaluateResearchAttempt(new(Guid.NewGuid(),flight.Id,start,time,CardId:p.Card.Id),science:f.Science);
    }
    [PostgresFact] public async Task CoverageGoalsUseAuthorizedCasIdempotentCommandsPagedHistoryAndIsolatedOrganizations()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(AtmosphericResearch.Template);var path=$"/campaigns/{c.Published.CampaignId}/coverage/goals";var command=new CoverageGoalSave(1,Guid.NewGuid(),0,TemperatureGoal(c.Published));var first=(await f.Server.Post(Progress+path,command)).Deserialize<CoverageGoalView>(WireJson.Options)!;var duplicate=(await f.Server.Post(Progress+path,command)).Deserialize<CoverageGoalView>(WireJson.Options)!;Assert.Equal(first,duplicate);
        using(var replay=await ReviewSend(f.Server,Progress+path,command with{Definition=command.Definition with{Name="Changed under an old identity"}}))Assert.Equal(HttpStatusCode.Conflict,replay.StatusCode);
        var next=command with{RequestId=Guid.NewGuid(),ExpectedRevision=1,Definition=command.Definition with{MinimumPilots=3}};var competing=await Task.WhenAll(ReviewSend(f.Server,Progress+path+"/"+first.Id,next,method:HttpMethod.Put),ReviewSend(f.Server,Progress+path+"/"+first.Id,next with{RequestId=Guid.NewGuid(),Definition=next.Definition with{MinimumPilots=4}},method:HttpMethod.Put));Assert.Single(competing,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(competing,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var response in competing)response.Dispose();Assert.Equal(2,(await ProgressGet<OrganizationPage<CoverageGoalView>>(f,$"/coverage-goals/{first.Id}/history")).Items.Length);
        for(var i=0;i<20;i++)await CoverageSave(f,c.Published,command.Definition with{Name="Paged goal "+i.ToString("D2")});var page=await ProgressGet<OrganizationPage<CoverageGoalView>>(f,path);Assert.Equal(20,page.Items.Length);Assert.Equal(20,page.NextOffset);Assert.Single((await ProgressGet<OrganizationPage<CoverageGoalView>>(f,path+"?offset=20")).Items);
        using var pilot=await ProgressPilot(f,"coverage-member");using(var denied=await ReviewSend(f.Server,Progress+path,command with{RequestId=Guid.NewGuid()},pilot))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);Assert.Equal(20,(await pilot.GetFromJsonAsync<OrganizationPage<CoverageGoalView>>(Progress+path,WireJson.Options))!.Items.Length);
        using var native=new HttpClient{BaseAddress=new(f.Server.Origin)};native.DefaultRequestHeaders.Authorization=new("Bearer",f.Vault.Read(f.Read));using(var denied=await native.PostAsJsonAsync("/api/member/research-progress"+path,command,WireJson.Options))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        await using(var other=await SubmissionFixture.Create()){using var denied=await other.Server.Browser.GetAsync(Progress+$"/coverage-goals/{first.Id}/assessment");Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);}
        var member=(await ReviewGet<OrganizationPage<OrganizationMemberView>>(f.Server,"/api/organization/members")).Items.Single(m=>m.Name=="coverage-member");await f.Server.Post("/api/organization/members/"+member.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),member.Revision,member.Role,OrganizationMembershipState.Suspended),HttpMethod.Put);using(var denied=await pilot.GetAsync(Progress+$"/campaigns/{c.Published.CampaignId}/coverage"))Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);
    }
    [PostgresFact] public async Task CoverageThreePilotCampaignCountsActualBandsDeduplicatesUploadsAndSeparatesPressureAndRevisionGoals()
    {
        await using var f=await SubmissionFixture.Create();var parent=await RealOpportunity(f.Server,AtmosphericResearch.Template);var card=await ProgressCard(f,parent,"Atmospheric Temperature Profiling Campaign",new(OrganizationParticipation.MultiPilot,3,3,true,[OrganizationRoles.Administrator,OrganizationRoles.Pilot],"Independent original scientific observations"));var path=$"/campaigns/{card.CampaignId}/coverage";
        using var a=await ProgressPilot(f,"profile-b");using var b=await ProgressPilot(f,"profile-c");var servers=new[]{f.Server,new Server(f.Server.App,a,f.Server.Origin,f.Database),new Server(f.Server.App,b,f.Server.Origin,f.Database)};var inputs=new[]{(1000,4000),(3000,6000),(7000,9000)};var rows=new List<SubmissionDraft>();PersonalResearchAttempt? first=null;
        using var delivery=f.Delivery();for(var i=0;i<3;i++){
            var claim=await BrowserClaim(servers[i],card);var connection=i==0?f.Upload:await Connect(f.Desktop,servers[i],OrganizationDesktopPermission.SubmitEvidence);var preview=await f.Desktop.PreviewMission(connection,claim.Id,new(),f.Store,default);var saved=await f.Desktop.PrepareMission(connection,claim.Id,MissionSave(preview),f.Store,default);var attempt=await CoverageRecord(f,saved,inputs[i].Item1,inputs[i].Item2);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,attempt.Outcome);first??=attempt;
            var row=f.Store.SaveSubmissionDraft(new(1,Guid.NewGuid(),0,attempt.FlightId,[attempt.Id],null,"Independently approved synthetic temperature profile",connection),f.Science);await f.Desktop.RefreshSubmissionPolicies(connection,row,f.Store,default);row=f.Store.SaveSubmissionDraft(MissionStore.SubmissionRequest(row),f.Science);var package=f.Store.PreviewSavedSubmission(row.Id,f.Science);await f.Desktop.ApproveSubmission(row.Id,new(1,row.Revision,package.ManifestSha256,package.PayloadSha256,package.PayloadBytes,connection,true),f.Store,f.Science,default);row=await delivery.Send(row.Id,default);Assert.Equal(SubmissionDeliveryState.ServerReceived,row.State);rows.Add(row);var review=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(row.Receipt!.Id));foreach(var q in review.Requirements)await ReviewCommand(f,row,ResearchReviewAction.Approve,"Accepted original synthetic temperature and pressure samples with their actual altitude evidence.",new(q.Requirement.CardId,q.Requirement.Key),[new(row.Receipt.Id,"*")]);
        }
        var goal=await CoverageSave(f,card,TemperatureGoal(card));var assessment=await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment");Assert.Equal(new long[]{1,2,2,2,1},assessment.Bands.Select(band=>band.Counts.Pilots));Assert.Equal(new bool?[]{false,true,true,true,false},assessment.Bands.Select(band=>band.Satisfied));Assert.Equal(3,assessment.Counts.Pilots);Assert.Equal(3,assessment.Counts.Flights);Assert.False(assessment.Complete);Assert.Equal(2,assessment.Gaps.Length);
        var groups=(await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items;Assert.Equal(2,groups.Length);Assert.Contains(groups,g=>g.Unit=="inHg"&&g.Instrument=="ambient-pressure");var temp=groups.Single(g=>g.Unit=="degC");Assert.Equal(assessment.Counts.Observations,temp.Observations);
        var repeated=await f.ReviewApprove(f.Draft(first!));repeated=await delivery.Send(repeated.Id,default);await ReviewCommand(f,repeated,ResearchReviewAction.Approve,"A second upload of the exact original observations is not a new measurement or independent contribution.",new(first!.Card.Id,"collection"),[new(repeated.Receipt!.Id,"*")]);var dedup=(await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items.Single(g=>g.Unit=="degC");Assert.Equal(temp.Observations,dedup.Observations);Assert.Equal(3,dedup.Pilots);Assert.True(dedup.DuplicateReferences>0);
        var dates=await ProgressGet<OrganizationPage<CoverageTemporalSlice>>(f,path+"/dates?compatibilityId="+temp.Id);Assert.Equal(temp.Observations,dates.Items.Sum(d=>d.Counts.Observations));Assert.Equal(temp.Observations-temp.Dates,dates.Items.Sum(d=>d.RepeatObservations));
        var changed=await CoverageSave(f,card,goal.Definition with{MinimumPilots=1,Altitude=new(0,12000,2000)},goal);var empty=await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment");Assert.Equal(0,empty.Bands.Last().Counts.Observations);Assert.False(empty.Complete);Assert.False((await ProgressGet<CoverageGoalView>(f,$"/coverage-goals/{goal.Id}?revision=1")).Current);
        using(var denied=await ReviewSend(f.Server,Progress+path+"/goals",new CoverageGoalSave(1,Guid.NewGuid(),0,goal.Definition),a))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var hidden=await a.GetAsync("/api/organization/reviews/"+rows[0].Receipt!.Id))Assert.Equal(HttpStatusCode.Forbidden,hidden.StatusCode);
        await f.Restart();var rebuilt=await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment?revision=1");Assert.Equal(assessment.Bands,rebuilt.Bands);Assert.Equal(assessment.Counts,rebuilt.Counts);Assert.Equal(4,(await ProgressGet<CampaignProgressView>(f,$"/campaigns/{card.CampaignId}")).Totals.ReceivedCards);Assert.Equal(3,(await ProgressGet<CampaignProgressView>(f,$"/campaigns/{card.CampaignId}")).Totals.ApprovedPilotContributions);
    }
    [PostgresFact] public async Task CoverageUsesApprovedOriginalReferencesGoalsAreVersionedAndRebuildIsIdempotent()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(AtmosphericResearch.Template);var path=$"/campaigns/{c.Published.CampaignId}/coverage";Assert.False((await ProgressGet<CampaignCoverageView>(f,path)).HasGoals);
        var attempt=await AtmosphericRecording(f,c.Prepared);var row=await f.ReviewApprove(f.Draft(attempt));using var delivery=f.Delivery();row=await delivery.Send(row.Id,default);Assert.Empty((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items);
        var snap=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(row.Receipt!.Id));foreach(var requirement in snap.Requirements)await ReviewCommand(f,row,ResearchReviewAction.Approve,"Approved original synthetic atmospheric observations, not a real-world hypothesis.",new(requirement.Requirement.CardId,requirement.Requirement.Key),[new(row.Receipt.Id,"*")]);
        var group=Assert.Single((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items);Assert.Equal(1,group.Pilots);Assert.Equal(1,group.Flights);Assert.Equal(CoverageEvidenceCategory.SyntheticFixture,group.Category);Assert.Equal("degC",group.Unit);Assert.True(group.Observations>0);Assert.Equal(group.Observations,group.LocatedObservations);
        var points=await ProgressGet<OrganizationPage<CoverageLocation>>(f,path+"/locations?compatibilityId="+group.Id);Assert.Equal(group.Observations,points.Items.LongLength);Assert.All(points.Items,p=>Assert.Equal(40,p.Latitude));
        var goal=await CoverageSave(f,c.Published,TemperatureGoal(c.Published));var assessed=await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment");Assert.False(assessed.Complete);Assert.Equal(5,assessed.Bands.Length);Assert.Contains(assessed.Bands,b=>b.Counts.Observations==0);Assert.All(assessed.Bands,b=>Assert.False(b.Satisfied));Assert.Contains(assessed.Gaps,g=>g.Contains("/2 distinct approved pilots"));
        var changed=await CoverageSave(f,c.Published,goal.Definition with{MinimumPilots=1,Altitude=new(1000,2500,500),Grid=new(39,-76,41,-74,2,2)},goal);var cells=await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment");Assert.Equal(4,cells.Cells.Length);Assert.Equal(3,cells.Cells.Count(c=>c.Counts.Observations==0));Assert.False(cells.Complete);Assert.Equal(2,(await ProgressGet<OrganizationPage<CoverageGoalView>>(f,$"/coverage-goals/{goal.Id}/history")).Items.Length);Assert.Equal(2,(await ProgressGet<CoverageGoalView>(f,$"/coverage-goals/{goal.Id}?revision=1")).Definition.MinimumPilots);
        using(var stale=await ReviewSend(f.Server,Progress+path+"/goals/"+goal.Id,new CoverageGoalSave(1,Guid.NewGuid(),1,goal.Definition)))Assert.Equal(HttpStatusCode.MethodNotAllowed,stale.StatusCode);
        var json=JsonSerializer.Serialize(points,WireJson.Options);Assert.DoesNotContain("pilotId",json);Assert.DoesNotContain("frame",json);Assert.DoesNotContain("value",json);Assert.DoesNotContain(f.Vault.Read(f.Upload)!,json);Assert.True((await f.Desktop.CampaignCoverage(f.Read,c.Published.CampaignId,default)).VerifiedNow);Assert.False((await f.Desktop.CampaignCoverage(f.Read,c.Published.CampaignId,default)).Value!.CanManage);
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();await using var tx=await db.Database.BeginTransactionAsync();await scope.ServiceProvider.GetRequiredService<CampaignProgressProjection>().Sync(row.Receipt.Id,default,true);await tx.CommitAsync();Assert.Equal(group.Observations,await db.CoverageObservations.LongCountAsync());Assert.All(typeof(CampaignCoverageObservation).GetProperties(),p=>Assert.DoesNotContain(p.Name,new[]{"Value","Text","Frame","PayloadJson"}));}
        await f.Restart();Assert.Equal(group.Observations,(await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items.Single().Observations);await ReviewCommand(f,row,ResearchReviewAction.Reject,"Approval superseded; original science remains unchanged.",new(c.Prepared.Card.Id,"collection"));Assert.Empty((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/groups")).Items);Assert.Equal(0,(await ProgressGet<CoverageGoalAssessment>(f,$"/coverage-goals/{goal.Id}/assessment")).Counts.Observations);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,f.Store.ResearchAttempt(attempt.Id).Outcome);
    }
